import numpy as np

def gbm_terminal(S0, mu, sigma, T, paths, seed):
    """(mean, median) of S_T over many exact draws."""
    z = np.random.default_rng(seed).standard_normal(paths)
    ST = S0 * np.exp((mu - sigma**2 / 2) * T + sigma * np.sqrt(T) * z)
    return float(np.mean(ST)), float(np.median(ST))
